      "rawText": "2026年5月以来，“电子工业大米”MLCC成为市场焦点。部分高规格型号价格相比年初翻三至五倍，热门型号从每千颗80元涨至350元，有的型号甚至涨了十倍，一两个小时涨幅超50%。现货市场货源趋紧，国际厂商优先保障大客户，原厂已发布两轮涨价通知，单次涨幅20% - 30%。此轮涨价吸引跨界“玩家”，但实际落地订单增长不明显。根源是AI领域变革，AI服务器对MLCC需求量大。产业人士预计至少涨到年底，高端产品持续紧缺，中低端消费级产能扩产相对容易，高端产能建设周期长。国内企业总体受益，但程度取决于多方面能力。 (AI生成)",
